import{_ as t,a0 as r,w as d,s as o,ao as p,I as n,x as a,a1 as i,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 CentOS 上使用 FirewallD 配置防火牆 | LCTT x X-CMD","titleTemplate":false,"description":"在 CentOS 上使用 FirewallD 配置防火牆 | LCTT (201705) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 CentOS 上使用 FirewallD 配置防火牆 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 CentOS 上使用 FirewallD 配置防火牆 | LCTT (201705) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201705/20170213 Set Up and Configure a Firewall with FirewallD on CentOS 7","title":"在 CentOS 上使用 FirewallD 配置防火牆","tag":"201705","desc":""},"relativePath":"201705/20170213 Set Up and Configure a Firewall with FirewallD on CentOS 7.md","filePath":"[post].md"}'),h={name:"201705/20170213 Set Up and Configure a Firewall with FirewallD on CentOS 7.md"};function c(g,s,m,f,u,b){const e=r("Link");return d(),o("div",null,[s[19]||(s[19]=p(`<h1 id="在-centos-上使用-firewalld-配置防火牆" tabindex="-1">在 CentOS 上使用 FirewallD 配置防火牆 <a class="header-anchor" href="#在-centos-上使用-firewalld-配置防火牆" aria-label="Permalink to “在 CentOS 上使用 FirewallD 配置防火牆”">​</a></h1><p><img src="https://www.rosehosting.com/blog/wp-content/uploads/2017/02/set-up-and-configure-a-firewall-with-firewalld-on-centos-7.jpg" alt=""></p><p>FirewallD 是 CentOS 7 服務器上默認使用的防火牆管理工具。從根本上來講，它是在 iptables 基礎上的一個包裝，它同時擁有圖形配置工具 firewall-config 和命令列工具 firewall-cmd。使用 iptables 服務的話，每次更改設置後都要求刷新舊的規則，然後從文件 <code>/etc/sysconfig/iptables</code> 中讀取新的規則，然而 firewalld 只對差異進行改動。</p><h3 id="firewalld-區域" tabindex="-1">FirewallD 區域 <a class="header-anchor" href="#firewalld-區域" aria-label="Permalink to “FirewallD 區域”">​</a></h3><p>FirewallD 使用服務和區域代替 iptables 的規則和鏈。默認下面的區域都是可用的：</p><ul><li><p>drop——任何流入網絡的包都被丟棄，不作出任何響應，只允許流出的網絡連接。</p></li><li><p>block——任何進入的網絡連接都被拒絕，並返回 IPv4 的 icmp-host-prohibited 報文。只允許流出的網絡連接。</p></li><li><p>public——只接受選中的傳入網絡連接，例如在公共場合。</p></li><li><p>public——用於啓用偽裝的外部網絡，只接受被選中的傳入網絡連接。</p></li><li><p>dmz——隔離區域(demilitarized zone),有限制地公開訪問內部網絡，只接受被選中的傳入網絡連接。</p></li><li><p>work——用於工作區域中的計算機，只接受選中的流入網絡連接。</p></li><li><p>home——用於家庭區域中的計算機，只接受選中的流入網絡連接。</p></li><li><p>internal——用於內部網絡中的計算機，只接受選中的流入網絡連接。</p></li><li><p>trusted——所有的網絡連接都可以接受。</p></li></ul><p>要顯示所有可用的區域可以運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --get-zones</span></span>
<span class="line"><span>work drop internal external trusted home dmz public block</span></span></code></pre></div><p>要顯示默認的區域：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --get-default-zone</span></span>
<span class="line"><span>public</span></span></code></pre></div><p>改變默認的區域：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --set-default-zone=dmz</span></span>
<span class="line"><span># firewall-cmd --get-default-zone</span></span>
<span class="line"><span>dmz</span></span></code></pre></div><h3 id="firewalld-服務" tabindex="-1">FirewallD 服務 <a class="header-anchor" href="#firewalld-服務" aria-label="Permalink to “FirewallD 服務”">​</a></h3><p>FirewallD服務是 xml 配置文件，每個文件裏面記錄有防火牆針對某項服務的配置信息。要列出所有可用的服務，運行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --get-services</span></span>
<span class="line"><span>amanda-client amanda-k5-client bacula bacula-client ceph ceph-mon dhcp dhcpv6 dhcpv6-client dns docker-registry dropbox-lansync freeipa-ldap freeipa-ldaps freeipa-replication ftp high-availability http https imap imaps ipp ipp-client ipsec iscsi-target kadmin kerberos kpasswd ldap ldaps libvirt libvirt-tls mdns mosh mountd ms-wbt mysql nfs ntp openvpn pmcd pmproxy pmwebapi pmwebapis pop3 pop3s postgresql privoxy proxy-dhcp ptp pulseaudio puppetmaster radius rpc-bind rsyncd samba samba-client sane smtp smtps snmp snmptrap squid ssh synergy syslog syslog-tls telnet tftp tftp-client tinc tor-socks transmission-client vdsm vnc-server wbem-https xmpp-bosh xmpp-client xmpp-local xmpp-server</span></span></code></pre></div><p>xml 配置文件存放在 <code>/usr/lib/firewalld/services/</code> 和 <code>/etc/firewalld/services/</code> 目錄內。</p><h3 id="使用-firewalld-配置你的防火牆" tabindex="-1">使用 FirewallD 配置你的防火牆 <a class="header-anchor" href="#使用-firewalld-配置你的防火牆" aria-label="Permalink to “使用 FirewallD 配置你的防火牆”">​</a></h3>`,17)),n("p",null,[s[1]||(s[1]=a("作為一個例子，如果你正在運行一個 web 服務器、7022端口上的 SSH 和 mail 服務器，這裏會告訴你如何用 FirewallD 配置你的 ",-1)),i(e,{href:"6"},{default:l(()=>[...s[0]||(s[0]=[a("RoseHosting VPS",-1)])]),_:1}),s[2]||(s[2]=a(" 防火牆。",-1))]),s[20]||(s[20]=p(`<p>我們首先設置默認區域為 dmz：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --set-default-zone=dmz</span></span>
<span class="line"><span># firewall-cmd --get-default-zone</span></span>
<span class="line"><span>dmz</span></span></code></pre></div><p>為了將 HTTP 和 HTTPS 的服務規則永久加入 dmz 區域，運行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --zone=dmz --add-service=http --permanent</span></span>
<span class="line"><span># firewall-cmd --zone=dmz --add-service=https --permanent</span></span></code></pre></div><p>打開 25 端口SMTP)和 465 端口(SMTPS):</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --zone=dmz --add-service=smtp --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=smtps --permanent</span></span></code></pre></div><p>打開 IMAP、IMAPS、POP3 和 POP3S端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --zone=dmz --add-service=imap --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=imaps --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=pop3 --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=pop3s --permanent</span></span></code></pre></div><p>因為 SSH 端口號已經被改為 7022，所以我們將刪除 ssh 服務(端口 22)，然後開啓端口 7022：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --remove-service=ssh --permanent </span></span>
<span class="line"><span>firewall-cmd --add-port=7022/tcp --permanent</span></span></code></pre></div><p>為了讓這些改變生效，我們需要用命令重新加載防火牆：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --reload</span></span></code></pre></div><p>最後，你可以使用命令列出規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>### firewall-cmd –list-all</span></span>
<span class="line"><span>dmz</span></span>
<span class="line"><span>target: default</span></span>
<span class="line"><span>icmp-block-inversion: no</span></span>
<span class="line"><span>interfaces:</span></span>
<span class="line"><span>sources:</span></span>
<span class="line"><span>services: http https imap imaps pop3 pop3s smtp smtps</span></span>
<span class="line"><span>ports: 7022/tcp</span></span>
<span class="line"><span>protocols:</span></span>
<span class="line"><span>masquerade: no</span></span>
<span class="line"><span>forward-ports:</span></span>
<span class="line"><span>sourceports:</span></span>
<span class="line"><span>icmp-blocks:</span></span>
<span class="line"><span>rich rules:</span></span></code></pre></div><hr>`,15)),n("p",null,[s[4]||(s[4]=a("當然，如果您使用我們的 ",-1)),i(e,{href:"https://www.rosehosting.com/centos-vps.html"},{default:l(()=>[...s[3]||(s[3]=[a("CentOS VPS hosting",-1)])]),_:1}),s[5]||(s[5]=a(" 服務中任何一種服務，您都不必親自做上面任何設置，您可以讓我們專業的 Linux 管理員來為您設置。他們提供 24x7 的服務，並且會立即處理您的要求。",-1))]),s[21]||(s[21]=n("p",null,"PS：如果您喜歡這篇文章，請將它分享到社交平台上與您的朋友共享，或者僅僅在下面留言回覆。謝謝！",-1)),s[22]||(s[22]=n("hr",null,null,-1)),n("p",null,[s[7]||(s[7]=a("via: ",-1)),i(e,{href:"https://www.rosehosting.com/blog/set-up-and-configure-a-firewall-with-firewalld-on-centos-7/"},{default:l(()=>[...s[6]||(s[6]=[a("https://www.rosehosting.com/blog/set-up-and-configure-a-firewall-with-firewalld-on-centos-7/",-1)])]),_:1})]),n("p",null,[s[11]||(s[11]=a("作者：",-1)),i(e,{href:"https://www.rosehosting.com/blog/set-up-and-configure-a-firewall-with-firewalld-on-centos-7/"},{default:l(()=>[...s[8]||(s[8]=[a("rosehosting.com",-1)])]),_:1}),s[12]||(s[12]=a(" 譯者：",-1)),i(e,{href:"https://github.com/zhousiyu325"},{default:l(()=>[...s[9]||(s[9]=[a("zhousiyu325",-1)])]),_:1}),s[13]||(s[13]=a(" 校對：",-1)),i(e,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:l(()=>[...s[10]||(s[10]=[a("校對者ID",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:l(()=>[...s[15]||(s[15]=[a("Linux中國",-1)])]),_:1}),s[18]||(s[18]=a(" 榮譽推出",-1))])])}const v=t(h,[["render",c]]);export{C as __pageData,v as default};
